public class Bank {
  private String bankName, area;

  // Declaration options:
  private String[] phoneNumber;   // Recommended for better readability
  private String phoneNo[];       // Also valid, but less readable
}

class Bank {
  public static void main(String[] args) {
    int[] phone = new int[3];  // Primitive type array

    phone[0] = 7120686;
    phone[1] = 7120687;
    phone[2] = 7120684;

    int count = 1;
    for(int i = 0; i < phone.length; ++i) {
      System.out.println("phone number " + count + ": " + phone[i]);
      ++count;
    }
  }
}

class bank {
  public static void main(String[] args) {
    Customer[] customer = new Customer[2]; // Reference type array

    Customer customer1 = new Customer("Anil", "Acc12345");
    Customer customer2 = new Customer("Ajay", "Acc12346");

    customer[0] = customer1;
    customer[1] = customer2;

    for (int i = 0; i < customer.length; i++) {
      Customer custObj = customer[i];
      String name = custObj.displayCustomerName();
      System.out.println("The customer name is: " + name);
    }
  }
}

class Customer {
  private String name;
  private String customerId;

  Customer(String uname, String ucustomerId) {
    name = uname;
    customerId = ucustomerId;
  }

  public String displayCustomerName() {
    return name;
  }
}

